/**
 * Supabase Storage image store (3e, Josh 2026-11-18: generated essay images in served runs). Generated bytes go
 * to a public bucket of the run's own Supabase project — the same client and service-role key as the ledger and
 * tables, so no new secret — and the row's path is `<public_path>/<key>`, which the site serves from that bucket
 * (apps/site/src/pages/media/[...path].ts) on its own domain.
 *
 * - The bucket is created on first use (public, images only) if it does not exist; nothing else is configured.
 * - The key carries a short content hash (`<slug>/<variant>-<hash>.<ext>`), so a regenerated image never collides
 *   with a cached one and the site can cache every file as immutable.
 * - Placeholder SVGs are refused (IMAGE_STORE_STATIC): the placeholder adapter then records the deployed static
 *   placeholder, which the site never shows, instead of filling the bucket with brand art.
 */
import { createHash } from "node:crypto";
import type { ImageMime, ImageStore, ImageStoreInput, StageContext } from "@cc/shared";
import { IMAGE_STORE_STATIC, imageKey } from "./memory.ts";

interface StorageResult {
  data: unknown;
  error: { message: string } | null;
}

/** The slice of supabase-js `client.storage` this store uses (structural, so tests pass a fake). */
export interface SupabaseStorageLike {
  getBucket(id: string): Promise<StorageResult>;
  createBucket(id: string, options: { public: boolean; allowedMimeTypes?: string[]; fileSizeLimit?: string }): Promise<StorageResult>;
  from(bucket: string): {
    upload(path: string, body: Blob, options: { contentType: string; upsert: boolean; cacheControl: string }): Promise<StorageResult>;
  };
}

export interface SupabaseImageStoreOptions {
  storage: SupabaseStorageLike;
  bucket: string;
  /** Site path the bucket is served under, e.g. `/media`. */
  publicPath: string;
}

export const IMAGE_STORE_UPLOAD_FAILED = "IMAGE_STORE_UPLOAD_FAILED";
const ALLOWED_MIME: readonly ImageMime[] = ["image/webp", "image/png", "image/jpeg"];

/** `<slug>/<variant>-<sha256[0:10]>.<ext>`. */
export function hashedImageKey(input: Pick<ImageStoreInput, "slug" | "variant" | "mime" | "bytes">): string {
  const hash = createHash("sha256").update(input.bytes).digest("hex").slice(0, 10);
  return imageKey(input.slug, `${input.variant}-${hash}`, input.mime);
}

export function createSupabaseImageStore(options: SupabaseImageStoreOptions): ImageStore {
  let ready: Promise<void> | null = null;
  async function ensureBucket(): Promise<void> {
    const existing = await options.storage.getBucket(options.bucket);
    if (!existing.error) return;
    const created = await options.storage.createBucket(options.bucket, { public: true, allowedMimeTypes: [...ALLOWED_MIME], fileSizeLimit: "10MB" });
    if (created.error && !/already exists/i.test(created.error.message)) {
      throw new Error(`${IMAGE_STORE_UPLOAD_FAILED}: bucket ${options.bucket} could not be created: ${created.error.message}`);
    }
  }
  return {
    kind: "supabase",
    async put(input: ImageStoreInput, ctx: StageContext): Promise<{ path: string; bytes: number }> {
      if (!ALLOWED_MIME.includes(input.mime)) throw new Error(`${IMAGE_STORE_STATIC}: ${input.mime} is not hosted (placeholders stay static)`);
      if (input.bytes.byteLength === 0) throw new Error("IMAGE_STORE_EMPTY: no bytes to store");
      ready ??= ensureBucket().catch((error: unknown) => {
        ready = null; // let a later image retry the bucket check
        throw error;
      });
      await ready;
      const key = hashedImageKey(input);
      const uploaded = await options.storage
        .from(options.bucket)
        .upload(key, new Blob([input.bytes], { type: input.mime }), { contentType: input.mime, upsert: true, cacheControl: "31536000" });
      if (uploaded.error) throw new Error(`${IMAGE_STORE_UPLOAD_FAILED}: ${uploaded.error.message}`);
      ctx.logger.info("image: stored", { slug: input.slug, bucket: options.bucket, key, bytes: input.bytes.byteLength });
      return { path: `${options.publicPath}/${key}`, bytes: input.bytes.byteLength };
    },
  };
}
